const H = { "x-api-key": KEY, "anthropic-version": "2023-06-01", "content-type": "application/json" };
const t = () => ((Date.now() - T0) / 1000).toFixed(1);
const T0 = Date.now();

async function run(label: string, init: any) {
  const s = Date.now();
  try {
    const r = await fetch(URL, { method: "POST", headers: H, body: big, signal: AbortSignal.timeout(200000), ...init });
